#if UNITY_EDITOR
using System;using System.IO;using System.Collections;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace IslandSystem {
public class SprintHeadingReview:MonoBehaviour {
 IEnumerator Start(){yield return new WaitForSeconds(.5f);var motor=FindAnyObjectByType<ActionMotor>();motor.InputBlocked=true;motor.animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;motor.transform.rotation=Quaternion.identity;var text="";foreach(var state in new[]{"Idle","Walk","Run"}){Vector3 sum=Vector3.zero;for(int i=0;i<24;i++){motor.animator.Play(state,0,i/24f);motor.animator.Update(0);var left=motor.animator.GetBoneTransform(HumanBodyBones.LeftUpperLeg).position;var right=motor.animator.GetBoneTransform(HumanBodyBones.RightUpperLeg).position;sum+=Vector3.Cross(right-left,Vector3.up).normalized;}float yaw=Vector3.SignedAngle(Vector3.forward,sum,Vector3.up);text+=state+" pelvis forward yaw="+yaw+"\n";if(state=="Run"&&Mathf.Abs(yaw)>3){File.WriteAllText("Logs/SprintHeadingReview.txt",text);EditorApplication.Exit(2);yield break;}}for(int angle=90;angle<360;angle+=90){motor.transform.rotation=Quaternion.Euler(0,angle,0);Vector3 facing=Vector3.zero;for(int i=0;i<24;i++){motor.animator.Play("Run",0,i/24f);motor.animator.Update(0);facing+=Vector3.Cross(motor.animator.GetBoneTransform(HumanBodyBones.RightUpperLeg).position-motor.animator.GetBoneTransform(HumanBodyBones.LeftUpperLeg).position,Vector3.up).normalized;}float error=Vector3.SignedAngle(motor.transform.forward,facing,Vector3.up);text+="Run heading="+angle+" relative error="+error+"\n";if(Mathf.Abs(error)>3){File.WriteAllText("Logs/SprintHeadingReview.txt",text);EditorApplication.Exit(2);yield break;}}
  motor.transform.rotation=Quaternion.identity;motor.animator.Play("Run",0,.3f);motor.animator.Update(0);var cam=motor.view;var rt=new RenderTexture(1280,720,24);var old=cam.targetTexture;var active=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();Directory.CreateDirectory("Docs/IslandSystem/ActionTrial");File.WriteAllBytes("Docs/IslandSystem/ActionTrial/09-Sprint-Aligned.png",image.EncodeToPNG());cam.targetTexture=old;RenderTexture.active=active;Destroy(rt);Destroy(image);File.WriteAllText("Logs/SprintHeadingReview.txt",text);File.WriteAllText("Docs/IslandSystem/ActionTrial/SprintHeadingReview.txt",text);EditorApplication.isPlaying=false;}
}
[InitializeOnLoad]public static class SprintHeadingReviewEntry {
 static SprintHeadingReviewEntry(){if(SessionState.GetBool("SprintHeadingReview",false))EditorApplication.playModeStateChanged+=Attach;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/Lighthouse_Coast_ArtBenchmark_V01.unity");SessionState.SetBool("SprintHeadingReview",true);EditorApplication.playModeStateChanged+=Attach;EditorApplication.isPlaying=true;}
 static void Attach(PlayModeStateChange s){if(s==PlayModeStateChange.EnteredPlayMode)new GameObject("Background sprint heading review").AddComponent<SprintHeadingReview>();if(s==PlayModeStateChange.EnteredEditMode){SessionState.SetBool("SprintHeadingReview",false);EditorApplication.Exit(0);}}
}
}
#endif
